from typing import List

def largest_sub_grid(grid: List[List[int]], max_sum: int) -> int:
    n = len(grid)
    pre = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n):
        for j in range(n):
            pre[i + 1][j + 1] = grid[i][j] + pre[i][j + 1] + pre[i + 1][j] - pre[i][j]

    def can(k: int) -> bool:
        for i in range(n - k + 1):
            for j in range(n - k + 1):
                if pre[i + k][j + k] - pre[i][j + k] - pre[i + k][j] + pre[i][j] <= max_sum:
                    return True
        return False

    lo, hi = 0, n          # 不变式：lo 可行（k=0 视为总可行）
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if can(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

if __name__ == "__main__":
    # 按题面文字定义，1x1 的 2 <= 4 合法，所以答案是 1（题面样例写的 0 与定义矛盾）
    print(largest_sub_grid([[2, 2, 2], [3, 3, 3], [4, 4, 4]], 4))
